from __future__ import annotations
from dataclasses import dataclass
from typing import Iterator

@dataclass
class ISOItem:
    iso_code: int
    name: str
    short_code: str
    priority: int = 0

    def get_iso_code(self):
        return self.iso_code

    def get_name(self):
        return self.name

    def get_short_code(self):
        return self.short_code

    def get_priority(self):
        return self.priority

class ISOList:

    def __init__(self):
        self._items = []

    def add(self, iso_code, name, short_code, priority=0):
        self._items.append(ISOItem(int(iso_code), name, short_code, int(priority)))

    def get_count(self):
        return len(self._items)

    def get_at(self, index):
        if index < 0 or index >= len(self._items):
            raise IndexError('Array index out of bounds')
        return self._items[index]

    def __len__(self):
        return len(self._items)

    def __iter__(self) -> Iterator[ISOItem]:
        return iter(self._items)

    def __getitem__(self, i):
        return self._items[i]

class ISOCountryList(ISOList):
    pass

class ISOCurrencyList(ISOList):
    pass
